//go:build amd64

package floats

// The AVX2+FMA kernels of the mirror combiner (mirror.go), generated by go-asmgen
// (mirror_amd64_gen.go) into mirror_amd64.s: two values of k per step, for a CPU with
// the AVX2+FMA of the other kernels (hasAVX2FMA, kernels_amd64.go); the portable loop
// otherwise. The Go code finishes the last value of k. No kernel keeps a pointer:
// go:noescape.
//
//go:noescape
func mirrorCombineAVX2(dst, z, w1, w2 []float64)

//go:noescape
func mirrorCombineSplitAVX2(dst, z, w1, w2 []float64)

func mirrorCombine(dst, z, w1, w2 []float64, n int) {
	from := 1
	if hasAVX2FMA {
		mirrorCombineAVX2(dst, z, w1, w2)
		from = 1 + 2*((n-1)/2)
	}
	mirrorTail(dst, z, w1, w2, n, from)
}

func mirrorCombineSplit(dst, z, w1, w2 []float64, n int) {
	from := 1
	if hasAVX2FMA {
		mirrorCombineSplitAVX2(dst, z, w1, w2)
		from = 1 + 2*((n-1)/2)
	}
	mirrorSplitTail(dst, z, w1, w2, n, from)
}
